from mcp.server.fastmcp import FastMCP; import sqlite3; mcp = FastMCP('SQLite Mock'); db_path = 'mock_backend.db';
@mcp.tool(name='execute')
def execute(sql: str) -> str:
    conn = sqlite3.connect(db_path); cursor = conn.cursor()
    try: cursor.execute(sql); conn.commit(); return 'SUCCESS'
    except Exception as e: return f'ERROR: {e}'
    finally: conn.close()
@mcp.tool(name='query')
def query(sql: str) -> str:
    conn = sqlite3.connect(db_path); cursor = conn.cursor()
    try:
        cursor.execute(sql); rows = cursor.fetchall(); cols = [d[0] for d in cursor.description] if cursor.description else []
        return str([dict(zip(cols, r)) for r in rows])
    except Exception as e: return f'ERROR: {e}'
    finally: conn.close()
mcp.run()
